-- Remove rows using the new ENUM value
DELETE FROM dac_automation_rules WHERE rule = 'AUTO_OPEN_DAR_FOR_ALL_MEMBERS';
-- Create new ENUM type
CREATE TYPE dac_rule_type_new AS ENUM ('GRU_V1', 'HMB_V1', 'HMB_DSV1', 'GRU_DSV1');
-- Alter column to use new type
ALTER TABLE dac_automation_rules ALTER COLUMN rule TYPE dac_rule_type_new USING rule::text::dac_rule_type_new;
-- Drop old type
DROP TYPE dac_rule_type;
-- Rename new type to original name
ALTER TYPE dac_rule_type_new RENAME TO dac_rule_type;
